#!/bin/bash
set -e

# Fix: Puppeteer failed to launch on Vercel (missing libnss3.so) because
# Next.js's build was bundling/stripping @sparticuz/chromium's binary files.
# serverExternalPackages tells Next.js to leave these packages alone.
# Run this from your veda-hmis repo root in Codespaces.

echo "" | base64 -d > "next.config.js"
echo "Wrote next.config.js"

git add next.config.js
git commit -m "Fix: externalize @sparticuz/chromium so Vercel build keeps its binary files"
git push

echo "Done. After Vercel redeploys, retest:"
echo "https://portal.vedaeyehospital.com/api/test-invoice-pdf/bf96cb51-46bd-45ad-8562-08665adba446"
